#!/usr/bin/env python
# -*- coding: utf-8 -*-
"""旧实验最终模型保留审计：仅生成清单，不提供删除或执行训练的入口。"""
import argparse
import base64
import csv
import hashlib
import json
import os
from pathlib import Path
import re
import stat
import tarfile
import time
import zipfile
import zlib


VERSION = "UAM_OLD_FINAL_ONLY_READONLY_V1_20261101"
PROJECT = Path("/home/SY/uam/UAGMC-main")
EVIDENCE_B64 = ""
OLD_RUNS = (
    "uam_100m_two_tracks_v1", "uam_100m_two_tracks_BC_v2",
    "uam_100m_3d_v1_MAIN", "uam_100m_3d_v1_smoke",
    "uam_21x7_700k_METHOD_FIRST_V1", "uam_21x7_700k_METHOD_FIRST_V2",
    "uam_round3_uagmc_causal_V1", "uam_80m_attribution_V4_FIXED",
    "uam_stage12_v2_20261007_033409", "uam_K2K3_supp60m_focus_v2",
    "uam500m_supplement70m_s3", "uam500m_supplement70m_s3_technical_smoke",
    "uam_H150_20261015_v2", "uam_A150_20261015_v2",
    "uam_CM150_20261015_v2", "uam_E123_K23_HAPPO_132_v1",
)
MODEL_EXTENSIONS = {".zip", ".pkl", ".pt", ".pth", ".ckpt", ".safetensors"}
RECORD_NAMES = {
    "manifest.json", "run_manifest.json", "cell_manifest.json", "contract.json",
    "task.json", "train_end.json", "done.json", "cell_summary.json",
    "stage12_model_summary.json", "summary.json",
}
CHECKPOINT_RE = re.compile(r"uam_ppo_(\d+)_steps[.]zip\Z")
TRIPLE_RE = re.compile(r"checkpoint_(\d+)[.]model[.]zip\Z")


def sha(data):
    return hashlib.sha256(data).hexdigest()


def read_record(path):
    """只读取小型JSON，不反序列化模型、pickle或PyTorch文件。"""
    if path.stat().st_size > 4 * 1024**2:
        raise ValueError("JSON超过审计大小上限")
    raw = path.read_bytes()
    value = json.loads(raw.decode("utf-8-sig"))
    canonical = json.dumps(value, sort_keys=True, ensure_ascii=False,
                           separators=(",", ":"), allow_nan=True).encode("utf-8")
    return value, sha(raw), sha(canonical)


def file_info(path, root, uid, device):
    """逐级拒绝软链接、跨设备和越界；同一账号本身不构成实验归属证据。"""
    relative = path.relative_to(root)
    current = root
    for part in relative.parts:
        current = current / part
        info = current.lstat()
        if stat.S_ISLNK(info.st_mode) or info.st_dev != device:
            raise ValueError("符号链接或跨设备路径")
    info = path.lstat()
    if not stat.S_ISREG(info.st_mode) or info.st_uid != uid or info.st_nlink != 1:
        raise ValueError("非常规文件、属主不同或存在硬链接")
    if path.resolve() != path or not path.is_relative_to(root):
        raise ValueError("真实路径越界")
    return info


def zip_steps(path):
    """只读取SB3的JSON元数据并检查ZIP完整性，绝不加载神经网络。"""
    with zipfile.ZipFile(path) as bundle:
        names = bundle.namelist()
        if len(names) != len(set(names)) or "data" not in names or "policy.pth" not in names:
            raise ValueError("不是预期SB3模型结构")
        if bundle.getinfo("data").file_size > 32 * 1024**2:
            raise ValueError("模型元数据过大")
        if any(item.file_size > 512 * 1024**2 for item in bundle.infolist()):
            raise ValueError("单个模型成员异常过大")
        if bundle.testzip() is not None:
            raise ValueError("最终模型ZIP校验失败")
        data = json.loads(bundle.read("data"))
        steps = data.get("num_timesteps")
        if type(steps) is not int or steps <= 0:
            raise ValueError("无法核对最终模型内部训练步数")
        return steps


def model_groups(cell):
    """仅识别我们源码中明确出现的两种成组保存命名。"""
    groups = []
    directory = cell / "checkpoints"
    if not directory.is_dir() or directory.is_symlink():
        return groups
    for path in sorted(directory.iterdir()):
        match = CHECKPOINT_RE.fullmatch(path.name)
        if match:
            step = int(match[1])
            groups.append((step, [path, directory / f"uam_ppo_vecnormalize_{step}_steps.pkl"]))
        match = TRIPLE_RE.fullmatch(path.name)
        if match:
            step = int(match[1])
            marker = directory / f"checkpoint_{step}.json"
            if marker.is_file() and not marker.is_symlink():
                document, _, _ = read_record(marker)
                expected = dict(model=path.name, norm=f"checkpoint_{step}.norm.pkl",
                                state=f"checkpoint_{step}.state.pt")
                if document.get("ready") is True and document.get("step") == step and all(
                        document.get(key) == value for key, value in expected.items()):
                    groups.append((step, [directory / filename for filename in expected.values()]))
    return groups


def final_bundle(cell, root, uid, device, target=0):
    """优先显式最终模型；没有显式最终模型时，必须有完成标记才能保留末点。"""
    final = [cell / "final_model.zip", cell / "final_vecnormalize.pkl"]
    groups = model_groups(cell)
    maximum = max((step for step, _ in groups), default=0)
    if all(path.is_file() for path in final):
        for path in final:
            if file_info(path, root, uid, device).st_size <= 0:
                raise ValueError("最终模型或归一化文件为空")
        steps = zip_steps(final[0])
        if steps < maximum or (target and steps != target):
            raise ValueError("最终模型步数早于checkpoint或不等于归档目标")
        return set(final), steps
    for name in ("TRAIN_END.json", "train_end.json", "done.json"):
        marker = cell / name
        if not marker.is_file():
            continue
        file_info(marker, root, uid, device)
        document, _, _ = read_record(marker)
        if not isinstance(document, dict):
            continue
        status = str(document.get("status", "")).upper()
        steps = document.get("actual_steps", document.get("steps", 0))
        if status not in {"COMPLETE", "COMPLETED", "VALID"} or type(steps) is not int:
            continue
        matching = [paths for step, paths in groups if step == steps == maximum]
        if len(matching) != 1 or (target and target != steps):
            continue
        for path in matching[0]:
            if file_info(path, root, uid, device).st_size <= 0:
                raise ValueError("末点成组文件为空")
        if zip_steps(matching[0][0]) == steps:
            return set(matching[0]), steps
    raise ValueError("未核实完整最终模型；整格保留，不把最大编号自动视为完成")


def walk_regular(root, uid, issues):
    """只遍历白名单实验；不跟随链接、挂载点或他人子目录。"""
    device = root.stat().st_dev
    result = []
    for folder, dirs, files in os.walk(root, followlinks=False,
                                       onerror=lambda error: issues.append(str(error))):
        parent = Path(folder)
        safe = []
        for name in dirs:
            child = parent / name
            info = child.lstat()
            if stat.S_ISLNK(info.st_mode) or info.st_dev != device or info.st_uid != uid:
                issues.append("目录排除：" + str(child))
            else:
                safe.append(name)
        dirs[:] = safe
        for name in files:
            path = parent / name
            try:
                file_info(path, root, uid, device)
                result.append(path)
            except (OSError, ValueError) as error:
                issues.append(str(path) + "：" + str(error))
    return result


def process_references(run_name, script_names):
    """仅报告进程引用，不结束任何进程；无法读取的进程单独列出。"""
    active, unreadable = [], []
    for process in Path("/proc").iterdir():
        if not process.name.isdigit() or int(process.name) == os.getpid():
            continue
        try:
            if process.stat().st_uid != os.getuid():
                continue
            arguments = (process / "cmdline").read_bytes().split(b"\0")
            strings = [item.decode("utf-8", "replace") for item in arguments if item]
            if any(run_name in item for item in strings) or any(
                    Path(item).name in script_names for item in strings):
                active.append(int(process.name))
        except OSError:
            unreadable.append(int(process.name))
    return active, unreadable


def anchor_map(evidence):
    result = {}
    for entry in evidence.get("anchors", []):
        result.setdefault(entry["raw"], []).append(entry)
        result.setdefault(entry["canonical"], []).append(entry)
    return result


def match_record(path, lookup):
    document, raw, canonical = read_record(path)
    entries = lookup.get(raw, lookup.get(canonical, []))
    return document, raw, entries


def source_plan(project, root, evidence, uid):
    """仅K2K3采用此补充核对；必须同时匹配源码、计划和84格登记，不按目录名放行。"""
    expected = evidence.get("source_contract")
    if not expected:
        return None
    script = project / expected["script"]["name"]
    file_info(script, project, uid, project.stat().st_dev)
    if sha(script.read_bytes()) != expected["script"]["sha256"]:
        return None
    plan = root / "PLAN.json"
    file_info(plan, root, uid, root.stat().st_dev)
    document, _, _ = read_record(plan)
    if any(document.get(key) != value for key, value in expected["fields"].items()):
        return None
    if document.get("steps_per_run") != expected["steps"]:
        return None
    specs = document.get("specs", [])
    actual = {json.dumps({"cell": item["cell"], "seed": item["seed"]}, sort_keys=True) for item in specs}
    wanted = {json.dumps(item, sort_keys=True) for item in expected["registered_cells"].values()}
    if len(specs) != 84 or actual != wanted:
        return None
    return expected


def audit_run(project, name, evidence):
    root = project / "serial_runs" / name
    summary = {"experiment": name, "status": "NOT_FOUND", "candidate_files": 0,
               "candidate_logical_GiB": 0, "candidate_allocated_GiB": 0,
               "verified_cells": 0, "blocked_cells": 0, "ownership_matches": 0}
    rows, matches, issues = [], [], []
    if not root.exists():
        return summary, rows, matches, issues
    uid = os.getuid()
    if root.is_symlink() or root.resolve() != root or root.stat().st_uid != uid:
        summary["status"] = "BLOCKED_PATH"
        return summary, rows, matches, ["实验根目录路径或属主异常：" + str(root)]
    files = walk_regular(root, uid, issues)
    models = {path for path in files if path.suffix.lower() in MODEL_EXTENSIONS}
    summary["all_model_files"] = len(models)
    lookup = anchor_map(evidence)
    try:
        verified_source = source_plan(project, root, evidence, uid)
    except (OSError, ValueError, KeyError, TypeError):
        verified_source = None
    roots_verified = []
    for path in files:
        if path.parent != root or path.suffix.lower() != ".json":
            continue
        try:
            document, raw, entries = match_record(path, lookup)
            for entry in entries:
                if entry.get("registered_cells"):
                    roots_verified.append(entry)
                    matches.append({"experiment": name, "server_record": str(path),
                                    "server_sha256": raw, "local_archive": entry["archive"],
                                    "archive_record": entry["record"], "scope": "root_plan"})
        except (OSError, ValueError, TypeError):
            pass
    cells = set()
    for path in models:
        parts = path.relative_to(root).parts
        if "checkpoints" in parts:
            index = parts.index("checkpoints")
            cells.add(root.joinpath(*parts[:index]))
        elif path.name in {"final_model.zip", "final_vecnormalize.pkl"}:
            cells.add(path.parent)
    active, unreadable = process_references(name, {item["name"] for item in evidence.get("scripts", [])})
    summary["active_pids"] = active
    summary["unreadable_processes"] = unreadable
    decisions = {}
    for cell in sorted(cells):
        owned, target, matched, cell_decisions = False, 0, [], {}
        try:
            # 根计划必须与本地归档逐字节或JSON内容匹配，且明确登记该格子。
            for entry in roots_verified:
                registered = entry["registered_cells"]
                if cell.name in registered:
                    owned, target = True, int(registered[cell.name])
                    break
            if verified_source and cell.name in verified_source["registered_cells"]:
                contract = cell / "contract.json"
                file_info(contract, root, uid, root.stat().st_dev)
                document, raw, _ = read_record(contract)
                expected = dict(verified_source["fields"],
                                **verified_source["registered_cells"][cell.name],
                                steps=verified_source["steps"])
                if all(document.get(key) == value for key, value in expected.items()):
                    owned, target = True, verified_source["steps"]
                    matched.append({"experiment": name, "server_record": str(contract),
                                    "server_sha256": raw, "local_archive": "本地源码+根计划+逐格合同",
                                    "archive_record": verified_source["script"]["name"], "scope": "source_contract"})
            for path in files:
                if path.name.lower() not in RECORD_NAMES:
                    continue
                if path.parent != cell and path.parent != cell / "analysis":
                    continue
                document, raw, entries = match_record(path, lookup)
                valid = [entry for entry in entries if not entry.get("registered_cells")]
                if valid:
                    owned = True
                    entry = valid[0]
                    matched.append({"experiment": name, "server_record": str(path),
                                    "server_sha256": raw, "local_archive": entry["archive"],
                                    "archive_record": entry["record"], "scope": "cell"})
                    if isinstance(document, dict) and type(document.get("steps")) is int:
                        target = target or document["steps"]
            if not owned:
                raise ValueError("未与本地历史归档匹配；同为SY账号或脚本名相似不足以放行")
            if active:
                raise ValueError("存在引用本批实验的活动进程，暂不列可删除")
            if issues:
                raise ValueError("存在未核验路径，候选降为保留待查")
            keep, final_steps = final_bundle(cell, root, uid, root.stat().st_dev, target)
            groups = model_groups(cell)
            for step, paths in groups:
                if not all(path in models for path in paths):
                    for path in paths:
                        if path in models:
                            cell_decisions[path] = ("REVIEW", "成组文件不齐，不自动处理", cell)
                    continue
                for path in paths:
                    file_info(path, root, uid, root.stat().st_dev)
                    if path in keep:
                        cell_decisions[path] = ("KEEP_FINAL", "最终模型配套文件", cell)
                    elif step <= final_steps:
                        cell_decisions[path] = ("CANDIDATE", "归档归属匹配且最终成组模型已保留；执行前另核进程", cell)
            for path in keep:
                cell_decisions[path] = ("KEEP_FINAL", "最终模型配套文件", cell)
            decisions.update(cell_decisions)
            matches.extend(matched)
            summary["verified_cells"] += 1
        except (OSError, ValueError, TypeError, zipfile.BadZipFile) as error:
            summary["blocked_cells"] += 1
            for path in models:
                if path.is_relative_to(cell) and path not in decisions:
                    decisions[path] = ("REVIEW", str(error), cell)
    for path in sorted(models):
        action, reason, cell = decisions.get(path, ("REVIEW", "非已确认的中间模型命名，保留待查", root))
        info = path.lstat()
        rows.append({"experiment": name, "cell": str(cell.relative_to(root)),
                     "action": action, "reason": reason, "path": str(path),
                     "bytes": info.st_size,
                     "allocated_bytes": getattr(info, "st_blocks", (info.st_size + 511) // 512) * 512,
                     "device": info.st_dev, "inode": info.st_ino, "uid": info.st_uid,
                     "nlink": info.st_nlink, "mtime_ns": info.st_mtime_ns})
    candidates = [row for row in rows if row["action"] == "CANDIDATE"]
    summary.update(status="AUDITED" if not issues and not active and not unreadable and not summary["blocked_cells"]
                   else "REVIEW_REQUIRED",
                   candidate_files=len(candidates), ownership_matches=len(matches),
                   candidate_logical_GiB=round(sum(row["bytes"] for row in candidates) / 1024**3, 3),
                   candidate_allocated_GiB=round(sum(row["allocated_bytes"] for row in candidates) / 1024**3, 3),
                   retained_final_files=sum(row["action"] == "KEEP_FINAL" for row in rows),
                   review_files=sum(row["action"] == "REVIEW" for row in rows))
    return summary, rows, matches, issues


def write_csv(path, rows, fields):
    with path.open("x", encoding="utf-8-sig", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=fields)
        writer.writeheader()
        writer.writerows(rows)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.parse_args()
    if os.name != "posix" or not Path("/proc").is_dir():
        raise RuntimeError("仅供指定Linux服务器生成审计清单；不在Windows处理实验目录")
    import pwd
    if os.getuid() == 0 or pwd.getpwuid(os.getuid()).pw_name != "SY":
        raise RuntimeError("只允许SY账号，不使用sudo或root")
    for path in (PROJECT, PROJECT / "serial_runs"):
        if not path.is_dir() or path.is_symlink() or path.resolve() != path:
            raise RuntimeError("项目路径不存在、为链接或被重定向：" + str(path))
    evidence = json.loads(zlib.decompress(base64.b64decode(EVIDENCE_B64)))
    parent = PROJECT / "cleanup_audits"
    if parent.exists() and (parent.is_symlink() or parent.resolve() != parent):
        raise RuntimeError("审计输出目录为链接或被重定向")
    parent.mkdir(exist_ok=True)
    out = parent / ("old_final_only_" + time.strftime("%Y%m%d_%H%M%S") + "_" + str(os.getpid()))
    out.mkdir()
    summaries, rows, matches, issues = [], [], [], []
    for name in OLD_RUNS:
        result, detail, proof, errors = audit_run(PROJECT, name, evidence.get(name, {}))
        summaries.append(result)
        rows.extend(detail)
        matches.extend(proof)
        issues.extend(errors)
        print(json.dumps(result, ensure_ascii=False), flush=True)
    fields = ["experiment", "cell", "action", "reason", "path", "bytes", "allocated_bytes",
              "device", "inode", "uid", "nlink", "mtime_ns"]
    write_csv(out / "全部模型处置清单.csv", rows, fields)
    write_csv(out / "拟删除逐文件清单.csv", [row for row in rows if row["action"] == "CANDIDATE"], fields)
    write_csv(out / "归属证据匹配.csv", matches,
              ["experiment", "server_record", "server_sha256", "local_archive", "archive_record", "scope"])
    summary = {"version": VERSION, "deleted_files": 0, "new_training_transitions": 0,
               "runs": summaries, "issues": issues,
               "candidate_logical_GiB": round(sum(row["candidate_logical_GiB"] for row in summaries), 3),
               "candidate_allocated_GiB": round(sum(row["candidate_allocated_GiB"] for row in summaries), 3),
               "note": "只列清单；CANDIDATE不是执行授权。保留全部非模型结果；未核验范围不删除。"}
    with (out / "清点汇总.json").open("x", encoding="utf-8") as handle:
        json.dump(summary, handle, ensure_ascii=False, indent=2)
    with (out / "本地归档证据索引.json").open("x", encoding="utf-8") as handle:
        json.dump(evidence, handle, ensure_ascii=False, indent=2)
    archive = out / (out.name + "_AUDIT_ONLY.tar.gz")
    with tarfile.open(archive, "x:gz") as bundle:
        for path in sorted(out.iterdir()):
            if path != archive:
                bundle.add(path, arcname=path.name, recursive=False)
    print("\n[清单目录] " + str(out))
    print("[审计数据包] " + str(archive))
    print("[拟删除逻辑大小GiB] " + str(summary["candidate_logical_GiB"]))
    print("[拟删除文件已分配磁盘GiB] " + str(summary["candidate_allocated_GiB"]))
    print("[本次删除0个文件；没有加载模型、没有训练、没有停止进程。]")


if __name__ == "__main__":
    main()
